-- Doc Motor Fase 3.13: catálogo central de modificações e serviço de suspensão.
-- Migration incremental e não destrutiva. Executar manualmente após o precheck.

ALTER TABLE service_billing_items ADD COLUMN IF NOT EXISTS quantity_expression JSON NULL;

CREATE TABLE IF NOT EXISTS vehicle_modifications (
  id CHAR(36) NOT NULL PRIMARY KEY,
  code VARCHAR(80) NOT NULL,
  name VARCHAR(180) NOT NULL,
  category VARCHAR(80) NOT NULL,
  description VARCHAR(500) NULL,
  status VARCHAR(16) NOT NULL DEFAULT 'ACTIVE',
  display_order INT NOT NULL DEFAULT 0,
  billing_item_id CHAR(36) NULL,
  requires_prior_authorization TINYINT(1) NOT NULL DEFAULT 0,
  requires_csv TINYINT(1) NOT NULL DEFAULT 0,
  requires_ecv TINYINT(1) NOT NULL DEFAULT 0,
  requires_manual_review TINYINT(1) NOT NULL DEFAULT 0,
  requires_description TINYINT(1) NOT NULL DEFAULT 0,
  official_reference_url VARCHAR(500) NULL,
  guidance TEXT NULL,
  legal_status VARCHAR(32) NOT NULL DEFAULT 'A_CONFIRMAR',
  created_by CHAR(36) NULL,
  updated_by CHAR(36) NULL,
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  UNIQUE KEY uq_vehicle_modifications_code (code),
  KEY idx_vehicle_modifications_status_order (status, display_order),
  CONSTRAINT fk_vehicle_modification_billing FOREIGN KEY (billing_item_id) REFERENCES billing_items (id) ON DELETE SET NULL,
  CONSTRAINT fk_vehicle_modification_created_by FOREIGN KEY (created_by) REFERENCES users (id) ON DELETE SET NULL,
  CONSTRAINT fk_vehicle_modification_updated_by FOREIGN KEY (updated_by) REFERENCES users (id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS vehicle_modification_categories (
  modification_id CHAR(36) NOT NULL,
  vehicle_category_id CHAR(36) NOT NULL,
  PRIMARY KEY (modification_id, vehicle_category_id),
  CONSTRAINT fk_modification_categories_modification FOREIGN KEY (modification_id) REFERENCES vehicle_modifications (id) ON DELETE CASCADE,
  CONSTRAINT fk_modification_categories_vehicle FOREIGN KEY (vehicle_category_id) REFERENCES vehicle_categories (id) ON DELETE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS vehicle_modification_ufs (
  modification_id CHAR(36) NOT NULL,
  uf CHAR(2) NOT NULL,
  PRIMARY KEY (modification_id, uf),
  CONSTRAINT fk_modification_ufs_modification FOREIGN KEY (modification_id) REFERENCES vehicle_modifications (id) ON DELETE CASCADE,
  CONSTRAINT fk_modification_ufs_state FOREIGN KEY (uf) REFERENCES brazilian_states (uf) ON DELETE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS vehicle_modification_documents (
  id CHAR(36) NOT NULL PRIMARY KEY,
  modification_id CHAR(36) NOT NULL,
  document_code VARCHAR(80) NOT NULL,
  name VARCHAR(180) NOT NULL,
  requirement_type VARCHAR(24) NOT NULL DEFAULT 'A_CONFIRMAR',
  description VARCHAR(500) NULL,
  condition_expression JSON NULL,
  display_order INT NOT NULL DEFAULT 0,
  UNIQUE KEY uq_modification_document (modification_id, document_code),
  CONSTRAINT fk_modification_documents_modification FOREIGN KEY (modification_id) REFERENCES vehicle_modifications (id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS vehicle_modification_messages (
  id CHAR(36) NOT NULL PRIMARY KEY,
  modification_id CHAR(36) NOT NULL,
  message_key VARCHAR(80) NOT NULL,
  severity VARCHAR(16) NOT NULL DEFAULT 'INFO',
  content VARCHAR(1000) NOT NULL,
  condition_expression JSON NULL,
  display_order INT NOT NULL DEFAULT 0,
  UNIQUE KEY uq_modification_message (modification_id, message_key),
  CONSTRAINT fk_modification_messages_modification FOREIGN KEY (modification_id) REFERENCES vehicle_modifications (id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

UPDATE services SET name = 'Regularização de suspensão', slug = 'regularizacao-de-suspensao', short_description = 'Orientação para rebaixamento, elevação, kits Lift e outras alterações de suspensão.', updated_at = UTC_TIMESTAMP() WHERE code = 'LOWERED_SUSPENSION';

