INSERT INTO vehicle_modification_categories (modification_id, vehicle_category_id)
SELECT vm.id, vc.id FROM vehicle_modifications vm CROSS JOIN vehicle_categories vc WHERE vm.code IN ('SUSPENSION_LOWERING', 'SUSPENSION_LIFT', 'SUSPENSION_OTHER', 'WHEELS_TIRES', 'GNV_INSTALLATION', 'GNV_REMOVAL', 'FUEL_CHANGE', 'SECURITY_ARMOR_INSTALLATION', 'SECURITY_ARMOR_REMOVAL', 'POWER_CHANGE', 'CYLINDER_CHANGE', 'BODY_CHANGE', 'MOTORHOME_CONVERSION', 'CHASSIS_LENGTHENING', 'CHASSIS_SHORTENING', 'AXLE_ADDITION', 'PCD_ADAPTATION', 'DRIVING_SCHOOL_CONTROLS_INSTALLATION', 'DRIVING_SCHOOL_CONTROLS_REMOVAL', 'PASSENGER_CAPACITY_CHANGE', 'COLOR_CHANGE', 'WRAPPING', 'LOAD_DEVICE_CHANGE', 'SPECIES_COLLECTION', 'SPECIES_COMPETITION', 'SPECIES_OTHER', 'OTHER_MODIFICATION') AND vc.code IN ('AUTOMOBILE', 'PICKUP') ON DUPLICATE KEY UPDATE modification_id = VALUES(modification_id);

INSERT INTO service_versions (id, service_id, version_number, status, change_summary)
SELECT '57000000-0000-4000-8000-000000000001', s.id, 1, 'DRAFT', 'Configuração inicial declarativa da regularização de suspensão.' FROM services s WHERE s.code = 'LOWERED_SUSPENSION' AND NOT EXISTS (SELECT 1 FROM service_versions v WHERE v.service_id = s.id);

INSERT INTO service_form_sections (id, service_version_id, stable_key, label, description, display_order)
SELECT x.id, v.id, x.stable_key, x.label, x.description, x.display_order FROM service_versions v JOIN services s ON s.id = v.service_id JOIN (SELECT '52000000-0000-4000-8000-000000000001' id, 'vehicle' stable_key, 'Dados do veículo' label, 'Informe os dados manualmente nesta fase.' description, 10 display_order UNION ALL SELECT '52000000-0000-4000-8000-000000000002', 'suspension', 'Modificação da suspensão', 'Selecione a alteração e as condições conhecidas.', 20 UNION ALL SELECT '52000000-0000-4000-8000-000000000003', 'wheels', 'Rodas e pneus', 'A regularização de rodas e pneus é uma única modificação comercial.', 30 UNION ALL SELECT '52000000-0000-4000-8000-000000000004', 'additional', 'Outras modificações', 'Adicione modificações distintas quando necessário.', 40) x WHERE s.code = 'LOWERED_SUSPENSION' AND v.version_number = 1 ON DUPLICATE KEY UPDATE label = VALUES(label), description = VALUES(description), display_order = VALUES(display_order);

INSERT INTO service_form_fields (id, service_version_id, section_id, field_key, label, description, field_type, is_required, display_order, visibility_condition, required_condition, data_origin)
SELECT f.id, v.id, sec.id, f.field_key, f.label, f.description, f.field_type, f.is_required, f.display_order, f.visibility_condition, f.required_condition, 'MANUAL' FROM service_versions v JOIN services s ON s.id = v.service_id JOIN (SELECT '53000000-0000-4000-8000-000000000001' id, 'vehicle_target.plate' field_key, 'Placa do veículo' label, 'Aceitamos placa antiga ou Mercosul.' description, 'VEHICLE_PLATE' field_type, 1 is_required, 10 display_order, NULL visibility_condition, NULL required_condition, 'vehicle' stable_key UNION ALL SELECT '53000000-0000-4000-8000-000000000002', 'vehicle_target.category', 'Categoria veicular', 'Casos não homologados seguem para análise manual.', 'SINGLE_SELECT', 1, 20, NULL, NULL, 'vehicle' UNION ALL SELECT '53000000-0000-4000-8000-000000000003', 'vehicle_target.state', 'UF do veículo', NULL, 'SINGLE_SELECT', 1, 30, NULL, NULL, 'vehicle' UNION ALL SELECT '53000000-0000-4000-8000-000000000004', 'vehicle_target.pbt_kg', 'PBT (kg), quando aplicável', 'Informe apenas quando souber.', 'INTEGER', 0, 40, NULL, NULL, 'vehicle' UNION ALL SELECT '53000000-0000-4000-8000-000000000005', 'suspension.change_type', 'Tipo de alteração', NULL, 'SINGLE_SELECT', 1, 50, NULL, NULL, 'suspension' UNION ALL SELECT '53000000-0000-4000-8000-000000000006', 'suspension.type', 'Tipo de suspensão', NULL, 'SINGLE_SELECT', 1, 60, NULL, NULL, 'suspension' UNION ALL SELECT '53000000-0000-4000-8000-000000000007', 'suspension.already_done', 'A modificação já foi realizada?', NULL, 'YES_NO', 1, 70, NULL, NULL, 'suspension' UNION ALL SELECT '53000000-0000-4000-8000-000000000008', 'suspension.prior_authorization', 'Já possui autorização prévia do Detran?', NULL, 'SINGLE_SELECT', 1, 80, NULL, NULL, 'suspension' UNION ALL SELECT '53000000-0000-4000-8000-000000000009', 'suspension.compliance', 'A instalação da suspensão respeita as regras do Detran?', 'Não selecione automaticamente. A resposta é orientativa.', 'SINGLE_SELECT', 1, 90, NULL, NULL, 'suspension' UNION ALL SELECT '53000000-0000-4000-8000-000000000010', 'suspension.clearance_check', 'O veículo possui altura livre mínima de 10 cm entre o solo e o ponto mais baixo da carroceria ou chassi?', 'Aplicável inicialmente a veículos de até 3.500 kg.', 'SINGLE_SELECT', 0, 100, '{"field":"suspension.compliance","operator":"EQUALS","value":"UNKNOWN"}', '{"field":"suspension.compliance","operator":"EQUALS","value":"UNKNOWN"}', 'suspension' UNION ALL SELECT '53000000-0000-4000-8000-000000000011', 'suspension.contact_check', 'As rodas e pneus não encostam durante o funcionamento?', NULL, 'SINGLE_SELECT', 0, 110, '{"field":"suspension.compliance","operator":"EQUALS","value":"UNKNOWN"}', '{"field":"suspension.compliance","operator":"EQUALS","value":"UNKNOWN"}', 'suspension' UNION ALL SELECT '53000000-0000-4000-8000-000000000012', 'wheels.include', 'Também deseja regularizar rodas e pneus?', NULL, 'YES_NO', 1, 120, NULL, NULL, 'wheels' UNION ALL SELECT '53000000-0000-4000-8000-000000000013', 'wheels.compliance', 'A instalação das rodas e pneus respeita as regras do Detran?', 'Não selecione automaticamente.', 'SINGLE_SELECT', 0, 130, '{"field":"wheels.include","operator":"EQUALS","value":"YES"}', '{"field":"wheels.include","operator":"EQUALS","value":"YES"}', 'wheels' UNION ALL SELECT '53000000-0000-4000-8000-000000000014', 'wheels.fender_check', 'Os pneus estão dentro dos limites dos para-lamas?', NULL, 'SINGLE_SELECT', 0, 140, '{"all":[{"field":"wheels.include","operator":"EQUALS","value":"YES"},{"field":"wheels.compliance","operator":"EQUALS","value":"UNKNOWN"}]}', NULL, 'wheels' UNION ALL SELECT '53000000-0000-4000-8000-000000000015', 'modifications.additional', 'Outras modificações', 'Use o catálogo para selecionar opções distintas e descreva cada alteração.', 'REPEATABLE_MODIFICATIONS', 0, 150, NULL, NULL, 'additional') f JOIN service_form_sections sec ON sec.service_version_id = v.id AND sec.stable_key = f.stable_key WHERE s.code = 'LOWERED_SUSPENSION' AND v.version_number = 1 ON DUPLICATE KEY UPDATE label = VALUES(label), description = VALUES(description), field_type = VALUES(field_type), is_required = VALUES(is_required), display_order = VALUES(display_order), visibility_condition = VALUES(visibility_condition), required_condition = VALUES(required_condition);

INSERT INTO service_field_options (id, field_id, option_value, option_label, display_order)
SELECT o.id, f.id, o.option_value, o.option_label, o.display_order FROM service_form_fields f JOIN (SELECT '54000000-0000-4000-8000-000000000001' id, 'vehicle_target.category' field_key, 'AUTOMOBILE' option_value, 'Automóvel' option_label, 10 display_order UNION ALL SELECT '54000000-0000-4000-8000-000000000002', 'vehicle_target.category', 'MOTORCYCLE', 'Motocicleta', 20 UNION ALL SELECT '54000000-0000-4000-000000000003', 'vehicle_target.category', 'TRUCK', 'Caminhão', 30 UNION ALL SELECT '54000000-0000-4000-8000-000000000004', 'vehicle_target.category', 'BUS', 'Ônibus', 40 UNION ALL SELECT '54000000-0000-4000-8000-000000000005', 'vehicle_target.category', 'PICKUP', 'Caminhonete', 50 UNION ALL SELECT '54000000-0000-4000-8000-000000000006', 'suspension.change_type', 'LOWERING', 'Rebaixamento', 10 UNION ALL SELECT '54000000-0000-4000-8000-000000000007', 'suspension.change_type', 'LIFT', 'Elevação / Kit Lift', 20 UNION ALL SELECT '54000000-0000-4000-8000-000000000008', 'suspension.change_type', 'OTHER', 'Outra alteração', 30 UNION ALL SELECT '54000000-0000-4000-8000-000000000009', 'suspension.type', 'FIXED', 'Fixa', 10 UNION ALL SELECT '54000000-0000-4000-8000-000000000010', 'suspension.type', 'COILOVER', 'Rosca', 20 UNION ALL SELECT '54000000-0000-4000-8000-000000000011', 'suspension.type', 'AIR', 'A ar', 30 UNION ALL SELECT '54000000-0000-4000-8000-000000000012', 'suspension.type', 'LIFT_KIT', 'Kit Lift', 40 UNION ALL SELECT '54000000-0000-4000-8000-000000000013', 'suspension.type', 'OTHER', 'Outra', 50 UNION ALL SELECT '54000000-0000-4000-8000-000000000014', 'suspension.type', 'UNKNOWN', 'Não sei', 60 UNION ALL SELECT '54000000-0000-4000-8000-000000000015', 'suspension.prior_authorization', 'YES', 'Sim', 10 UNION ALL SELECT '54000000-0000-4000-8000-000000000016', 'suspension.prior_authorization', 'NO', 'Não', 20 UNION ALL SELECT '54000000-0000-4000-8000-000000000017', 'suspension.prior_authorization', 'UNKNOWN', 'Não sei', 30 UNION ALL SELECT '54000000-0000-4000-8000-000000000018', 'suspension.compliance', 'YES', 'Sim', 10 UNION ALL SELECT '54000000-0000-4000-8000-000000000019', 'suspension.compliance', 'NO', 'Não', 20 UNION ALL SELECT '54000000-0000-4000-8000-000000000020', 'suspension.compliance', 'UNKNOWN', 'Não sei', 30 UNION ALL SELECT '54000000-0000-4000-8000-000000000021', 'suspension.clearance_check', 'YES', 'Sim', 10 UNION ALL SELECT '54000000-0000-4000-8000-000000000022', 'suspension.clearance_check', 'NO', 'Não', 20 UNION ALL SELECT '54000000-0000-4000-8000-000000000023', 'suspension.clearance_check', 'UNKNOWN', 'Não sei', 30 UNION ALL SELECT '54000000-0000-4000-8000-000000000024', 'suspension.contact_check', 'YES', 'Sim', 10 UNION ALL SELECT '54000000-0000-4000-8000-000000000025', 'suspension.contact_check', 'NO', 'Não', 20 UNION ALL SELECT '54000000-0000-4000-8000-000000000026', 'suspension.contact_check', 'UNKNOWN', 'Não sei', 30 UNION ALL SELECT '54000000-0000-4000-8000-000000000027', 'wheels.compliance', 'YES', 'Sim', 10 UNION ALL SELECT '54000000-0000-4000-8000-000000000028', 'wheels.compliance', 'NO', 'Não', 20 UNION ALL SELECT '54000000-0000-4000-8000-000000000029', 'wheels.compliance', 'UNKNOWN', 'Não sei', 30 UNION ALL SELECT '54000000-0000-4000-8000-000000000030', 'wheels.fender_check', 'YES', 'Sim', 10 UNION ALL SELECT '54000000-0000-4000-8000-000000000031', 'wheels.fender_check', 'NO', 'Não', 20 UNION ALL SELECT '54000000-0000-4000-8000-000000000032', 'wheels.fender_check', 'UNKNOWN', 'Não sei', 30) o ON o.field_key = f.field_key WHERE f.service_version_id = (SELECT id FROM service_versions sv JOIN services ss ON ss.id = sv.service_id WHERE ss.code = 'LOWERED_SUSPENSION' ORDER BY sv.version_number DESC LIMIT 1) ON DUPLICATE KEY UPDATE option_label = VALUES(option_label), display_order = VALUES(display_order);

INSERT INTO service_billing_items (id, service_version_id, billing_item_id, billing_mode, quantity_expression, display_order, condition_expression)
SELECT x.id, v.id, bi.id, x.billing_mode, x.quantity_expression, x.display_order, x.condition_expression FROM service_versions v JOIN services s ON s.id = v.service_id JOIN (SELECT '56000000-0000-4000-8000-000000000001' id, 'TRANSFER_FEE' code, 'REQUIRED' billing_mode, NULL quantity_expression, 10 display_order, NULL condition_expression UNION ALL SELECT '56000000-0000-4000-8000-000000000002', 'SERVICE_FEE', 'REQUIRED', NULL, 20, NULL UNION ALL SELECT '56000000-0000-4000-8000-000000000003', 'SUSPENSION_REGULARIZATION', 'REQUIRED', NULL, 30, NULL UNION ALL SELECT '56000000-0000-4000-8000-000000000004', 'MERCOSUR_PLATE_AUTHORIZATION', 'CONDITIONAL', NULL, 40, '{"field":"vehicle_target.plate_pattern","operator":"EQUALS","value":"OLD"}' UNION ALL SELECT '56000000-0000-4000-8000-000000000005', 'WHEELS_TIRES_REGULARIZATION', 'CONDITIONAL', NULL, 50, '{"field":"wheels.include","operator":"EQUALS","value":"YES"}' UNION ALL SELECT '56000000-0000-4000-8000-000000000006', 'ADDITIONAL_MODIFICATION', 'CONDITIONAL', '{"field":"modifications.additional","operator":"COUNT_FILLED"}', 60, '{"field":"modifications.additional","operator":"COUNT_FILLED"}') x JOIN billing_items bi ON bi.code = x.code WHERE s.code = 'LOWERED_SUSPENSION' AND v.version_number = 1 ON DUPLICATE KEY UPDATE billing_mode = VALUES(billing_mode), quantity_expression = VALUES(quantity_expression), display_order = VALUES(display_order), condition_expression = VALUES(condition_expression);

INSERT INTO technical_rules (id, service_id, service_version_id, name, description, conditions, expected_result, status, priority, version)
SELECT r.id, s.id, v.id, r.name, r.description, r.conditions, r.expected_result, 'DRAFT', r.priority, 1 FROM services s JOIN service_versions v ON v.service_id = s.id JOIN (SELECT '5A000000-0000-4000-8000-000000000001' id, 'Suspensão não conforme', 'A resposta negativa exige análise manual e não representa autorização.', '{"field":"suspension.compliance","operator":"EQUALS","value":"NO"}' conditions, 'MANUAL_REVIEW' expected_result, 10 priority UNION ALL SELECT '5A000000-0000-4000-8000-000000000002', 'Suspensão sem confirmação', 'Respostas desconhecidas ou incompatíveis exigem análise manual.', '{"any":[{"field":"suspension.compliance","operator":"EQUALS","value":"UNKNOWN"},{"field":"suspension.clearance_check","operator":"IN_LIST","values":["NO","UNKNOWN"]},{"field":"suspension.contact_check","operator":"IN_LIST","values":["NO","UNKNOWN"]}]}', 'MANUAL_REVIEW', 20 UNION ALL SELECT '5A000000-0000-4000-8000-000000000003', 'Rodas e pneus não conformes', 'A resposta negativa exige análise manual.', '{"field":"wheels.compliance","operator":"EQUALS","value":"NO"}', 'MANUAL_REVIEW', 30 UNION ALL SELECT '5A000000-0000-4000-8000-000000000004', 'Categoria sem regra específica', 'Motocicletas, veículos pesados e categorias não homologadas seguem para análise manual.', '{"field":"vehicle_target.category","operator":"IN_LIST","values":["MOTORCYCLE","TRUCK","BUS"]}', 'MANUAL_REVIEW', 40) r ON s.code = 'LOWERED_SUSPENSION' AND v.version_number = 1 WHERE NOT EXISTS (SELECT 1 FROM technical_rules existing WHERE existing.id = r.id);

INSERT INTO service_messages (id, service_version_id, message_key, severity, content, display_order)
SELECT m.id, v.id, m.message_key, m.severity, m.content, m.display_order FROM services s JOIN service_versions v ON v.service_id = s.id JOIN (SELECT '5B000000-0000-4000-8000-000000000001' id, 'EXTERNAL_COSTS_NOTE' message_key, 'INFO' severity, 'Os valores de inspeções, certificados e vistorias eventualmente exigidos não estão inclusos neste orçamento e serão cobrados diretamente pelas empresas responsáveis.' content, 10 display_order) m ON s.code = 'LOWERED_SUSPENSION' AND v.version_number = 1 ON DUPLICATE KEY UPDATE content = VALUES(content), severity = VALUES(severity), display_order = VALUES(display_order);

INSERT INTO schema_migrations (name)
SELECT '010_suspension_modification_catalog.sql'
WHERE NOT EXISTS (SELECT 1 FROM schema_migrations WHERE name = '010_suspension_modification_catalog.sql')
  AND (SELECT COUNT(*) FROM information_schema.tables WHERE table_schema = DATABASE() AND table_name IN ('vehicle_modifications', 'vehicle_modification_categories', 'vehicle_modification_ufs', 'vehicle_modification_documents', 'vehicle_modification_messages')) = 5
  AND (SELECT COUNT(*) FROM services WHERE code = 'LOWERED_SUSPENSION' AND name = 'Regularização de suspensão') = 1
  AND (SELECT COUNT(*) FROM vehicle_modifications) >= 27
  AND (SELECT COUNT(*) FROM service_form_fields f JOIN service_versions v ON v.id = f.service_version_id JOIN services s ON s.id = v.service_id WHERE s.code = 'LOWERED_SUSPENSION' AND f.field_key = 'modifications.additional') = 1;
